import { createAdabiLesson } from "../shared.js";

export const source = ":::exam-question\nid: math-t-p046-q01\ntitle: الكتاب · ص 44 · PDF 46 · السؤال 1\nquestion: أكتب الحدود الأربعة الأولى من مفكوك كل من المتسلسلات الآتية:\nreference: الكتاب · ص 44 · PDF 46 · السؤال 1\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nأكتب الحدود الأربعة الأولى من مفكوك كل من المتسلسلات الآتية:\n\n### المتسلسلة الحسابية ومجموعها — تمارين ومسائل (٣-٤)\n\n- أ) `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>7</mn></msubsup><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ر</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`.\n- ب) `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>17</mn></msubsup><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ر</mtext><mo stretchy=\"false\">)</mo></mrow></math>`.\nfinal-answer:\nأ) ٣، ٥، ٧، ٩. ب) ٢، ٤، ٦، ٨.\nsolution:\nدليل الحد يبدأ من ر = ١؛ نضع ر = ١، ٢، ٣، ٤ للحصول على الحدود الأربعة الأولى دون جمعها.\n\n- **أ:** `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>1</mn><mo>=</mo><mn>3</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>1</mn><mo>=</mo><mn>5</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>1</mn><mo>=</mo><mn>7</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>4</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>1</mn><mo>=</mo><mn>9</mn></mrow></math>`؛ فالحدود **٣، ٥، ٧، ٩**.\n- **ب:** `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>2</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>4</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>6</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>4</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>8</mn></mrow></math>`؛ فالحدود **٢، ٤، ٦، ٨**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-t-p046-q02\ntitle: الكتاب · ص 44 · PDF 46 · السؤال 2\nquestion: متسلسلة حسابية حدها الأول ١٤، وأساسها يساوي ٥، أجد مجموع أول ٢٠ حداً منها.\nreference: الكتاب · ص 44 · PDF 46 · السؤال 2\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nمتسلسلة حسابية حدها الأول ١٤، وأساسها يساوي ٥، أجد مجموع أول ٢٠ حداً منها.\n\n### المتسلسلة الحسابية ومجموعها — تمارين ومسائل (٣-٤)\nfinal-answer:\n١٢٣٠.\nsolution:\nالمعطيات: a = ١٤، d = ٥، ن = ٢٠. نطبق قانون مجموع المتسلسلة الحسابية:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext>د</mtext><mo stretchy=\"false\">]</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>20</mn></msub><mo>=</mo><mfrac><mn>20</mn><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>14</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>19</mn><mo stretchy=\"false\">(</mo><mn>5</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mn>10</mn><mo stretchy=\"false\">(</mo><mn>28</mn><mo>+</mo><mn>95</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>1230.</mn></mrow></math>`\n\nإذن **مجموع أول عشرين حدًّا ١٢٣٠**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-t-p046-q03\ntitle: الكتاب · ص 44 · PDF 46 · السؤال 3\nquestion: أجد الحد الأول في المتسلسلة الحسابية التي أساسها ٢ ومجموع أول ٦٠ حداً فيها يساوي ١٢٠.\nreference: الكتاب · ص 44 · PDF 46 · السؤال 3\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nأجد الحد الأول في المتسلسلة الحسابية التي أساسها ٢ ومجموع أول ٦٠ حداً فيها يساوي ١٢٠.\n\n### المتسلسلة الحسابية ومجموعها — تمارين ومسائل (٣-٤)\nfinal-answer:\nالحد الأول −٥٧.\nsolution:\nالمجهول هو الحد الأول a، والمعطيات d = ٢، ن = ٦٠، والمجموع ١٢٠. من قانون المجموع:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>120</mn><mo>=</mo><mfrac><mn>60</mn><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>59</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mn>30</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>118</mn><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>4</mn><mo>=</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>118</mn><mo>⇒</mo><mn>2</mn><mtext>أ</mtext><mo>=</mo><mo>−</mo><mn>114</mn><mo>⇒</mo><mtext>أ</mtext><mo>=</mo><mo>−</mo><mn>57.</mn></mrow></math>`\n\nإذن **الحد الأول −٥٧**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-t-p046-q04\ntitle: الكتاب · ص 44 · PDF 46 · السؤال 4\nquestion: كم حداً يجب أخذه من متسلسلة حسابية حدها الأول ٣ وأساسها ٦ ليكون مجموع تلك الحدود = ٢٧؟\nreference: الكتاب · ص 44 · PDF 46 · السؤال 4\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nكم حداً يجب أخذه من متسلسلة حسابية حدها الأول ٣ وأساسها ٦ ليكون مجموع تلك الحدود = ٢٧؟\n\n### المتسلسلة الحسابية ومجموعها — تمارين ومسائل (٣-٤)\nfinal-answer:\n٣ حدود.\nsolution:\nالحد الأول ٣ والأساس ٦. ليكن ن عدد الحدود؛ عندئذ:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mn>6</mn><mo stretchy=\"false\">]</mo><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><mn>6</mn><mtext>ن</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>3</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\nنضع المجموع ٢٧:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>3</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mo>=</mo><mn>27</mn><mo>⇒</mo><msup><mtext>ن</mtext><mn>2</mn></msup><mo>=</mo><mn>9.</mn></mrow></math>`\n\nعدد الحدود موجب، فنختار **ن = ٣**. وبالفعل `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>3</mn><mo>+</mo><mn>9</mn><mo>+</mo><mn>15</mn><mo>=</mo><mn>27</mn></mrow></math>`.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-t-p046-q05\ntitle: الكتاب · ص 44 · PDF 46 · السؤال 5\nquestion: متسلسلة حسابية حدها الأول ٣ وحدها الستون = ٨٧، أجد جـ₆₀.\nreference: الكتاب · ص 44 · PDF 46 · السؤال 5\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nمتسلسلة حسابية حدها الأول ٣ وحدها الستون = ٨٧، أجد جـ₆₀.\n\n### المتسلسلة الحسابية ومجموعها — تمارين ومسائل (٣-٤)\nfinal-answer:\n٢٧٠٠.\nsolution:\nنعرف عدد الحدود والحدين الأول والأخير، فنستخدم صيغة المجموع مباشرة:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>60</mn></msub><mo>=</mo><mfrac><mn>60</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>+</mo><msub><mtext>أ</mtext><mn>60</mn></msub><mo stretchy=\"false\">)</mo><mo>=</mo><mn>30</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo>+</mo><mn>87</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>30</mn><mo stretchy=\"false\">(</mo><mn>90</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>2700.</mn></mrow></math>`\n\nإذن **جـ₆₀ = ٢٧٠٠**؛ لا يلزم حساب الأساس.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::mcq\nid: math-t-p049-q03\ntitle: الكتاب · ص 47 · PDF 49 · السؤال 1-3\nkicker: الكتاب · ص 47 · PDF 49 · السؤال 1-3\nreference: الكتاب · ص 47 · PDF 49 · السؤال 1-3\nquestion: متسلسلة حسابية مجموع أول ستة عشر حداً فيها ٣٢، وأساسها −٢، ما حدها الأول؟\n- [ ] option-1 | ٣٤\n- [x] option-2 | ١٧\n- [ ] option-3 | ١٦\n- [ ] option-4 | −١٣\nexplanation:\nنستخدم مجموع المتسلسلة الحسابية `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mtext>ن</mtext><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">[</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext>د</mtext><mo stretchy=\"false\">]</mo></mrow></math>`، حيث `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext><mo>=</mo><mn>16</mn></mrow></math>` و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><mo>−</mo><mn>2</mn></mrow></math>` والمجموع ٣٢.\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>32</mn><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>16</mn><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">[</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>15</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mn>8</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>أ</mtext><mo>−</mo><mn>30</mn><mo stretchy=\"false\">)</mo></mrow></math>`.\n\nبقسمة الطرفين على ٨ نجد `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>4</mn><mo>=</mo><mn>2</mn><mtext>أ</mtext><mo>−</mo><mn>30</mn></mrow></math>`؛ إذن `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mtext>أ</mtext><mo>=</mo><mn>34</mn></mrow></math>` والحد الأول `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext><mo>=</mo><mn>17</mn></mrow></math>`.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### ورقة عمل — المعادلات والمتسلسلات\n:::\n\n:::exam-question\nid: math-t-p049-q06\ntitle: الكتاب · ص 47 · PDF 49 · السؤال 2\nquestion: أكتب أول ٥ حدود لمتسلسلة حسابية مجموع حديها الثاني والتاسع = ٢٥، ومجموع حديها الثالث والسابع = ٢٠.\nreference: الكتاب · ص 47 · PDF 49 · السؤال 2\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nأكتب أول ٥ حدود لمتسلسلة حسابية مجموع حديها الثاني والتاسع = ٢٥، ومجموع حديها الثالث والسابع = ٢٠.\n\n### ورقة عمل — المعادلات والمتسلسلات\nfinal-answer:\n−١٠، −٥، صفر، ٥، ١٠.\nsolution:\nنرمز للحد الأول بـ`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext></mrow></math>` وللأساس بـ`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext></mrow></math>`، ويكون الحد ذي الرتبة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext></mrow></math>` هو `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext>د</mtext></mrow></math>`.\n\nمن مجموع الحدين الثاني والتاسع نحصل على `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>8</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>25</mn></mrow></math>`، أي `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>9</mn><mtext>د</mtext><mo>=</mo><mn>25</mn></mrow></math>`.\n\nومن مجموع الحدين الثالث والسابع نحصل على `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>2</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>6</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>20</mn></mrow></math>`، أي `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>8</mn><mtext>د</mtext><mo>=</mo><mn>20</mn></mrow></math>`.\n\nبطرح المعادلتين نجد `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><mn>5</mn></mrow></math>`. نعوض في الثانية: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>40</mn><mo>=</mo><mn>20</mn></mrow></math>`، فيكون `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext><mo>=</mo><mo>−</mo><mn>10</mn></mrow></math>`.\n\nإذن أول خمسة حدود هي **−١٠، −٥، صفر، ٥، ١٠**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-t-p049-q08\ntitle: الكتاب · ص 47 · PDF 49 · السؤال 4\nquestion: إذا كان مجموع أول ن حداً من متسلسلة حسابية يعطى بالعلاقة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mtext>ن</mtext><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ن</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`، أجد الحد الأول والأساس لتلك المتسلسلة.\nreference: الكتاب · ص 47 · PDF 49 · السؤال 4\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nإذا كان مجموع أول ن حداً من متسلسلة حسابية يعطى بالعلاقة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mtext>ن</mtext><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ن</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`، أجد الحد الأول والأساس لتلك المتسلسلة.\n\n### ورقة عمل — المعادلات والمتسلسلات\nfinal-answer:\nالحد الأول ٣ والأساس ٤.\nsolution:\nالمعطى مجموع أول `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext></mrow></math>` حدًا: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mtext>ن</mtext><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ن</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>2</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mo>+</mo><mtext>ن</mtext></mrow></math>`.\n\nالحد الأول `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>1</mn></msub><mo>=</mo><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><mn>3</mn></mrow></math>`. ومجموع أول حدين `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>=</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>5</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>10</mn></mrow></math>`، لذلك الحد الثاني `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>2</mn></msub><mo>=</mo><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>−</mo><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><mn>10</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>7</mn></mrow></math>`.\n\nوبما أن المتسلسلة حسابية، فالأساس `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><msub><mtext>أ</mtext><mn>2</mn></msub><mo>−</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>=</mo><mn>7</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>4</mn></mrow></math>`. إذن **الحد الأول ٣ والأساس ٤**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::mcq\nid: math-t-p055-q01\ntitle: الكتاب · ص 53 · PDF 55 · السؤال 1-1\nkicker: الكتاب · ص 53 · PDF 55 · السؤال 1-1\nreference: الكتاب · ص 53 · PDF 55 · السؤال 1-1\nquestion: متسلسلة حسابية حدها الأول ٣ وحدها العاشر ٢١، ما مجموع أول عشرة حدود منها؟\n- [ ] option-1 | ٢٠\n- [ ] option-2 | ٤٠\n- [ ] option-3 | ٥٠\n- [x] option-4 | ١٢٠\nexplanation:\nعندما نعرف الحد الأول والأخير في متسلسلة حسابية نستخدم `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mtext>ن</mtext><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">(</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>+</mo><msub><mtext>أ</mtext><mtext>ن</mtext></msub><mo stretchy=\"false\">)</mo></mrow></math>`.\n\nهنا `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext><mo>=</mo><mn>10</mn></mrow></math>` و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>1</mn></msub><mo>=</mo><mn>3</mn></mrow></math>` و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>10</mn></msub><mo>=</mo><mn>21</mn></mrow></math>`، فيكون `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>10</mn></msub><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>10</mn><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">(</mo><mn>3</mn><mo>+</mo><mn>21</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>5</mn><mo>×</mo><mn>24</mn><mo>=</mo><mn>120</mn></mrow></math>`.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### تمارين عامة — الوحدة الثالثة\n:::\n\n:::mcq\nid: math-t-p057-q03\ntitle: الكتاب · ص 55 · PDF 57 · السؤال 1-3\nkicker: الكتاب · ص 55 · PDF 57 · السؤال 1-3\nreference: الكتاب · ص 55 · PDF 57 · السؤال 1-3\nquestion: إذا كان مجموع أول ن حدًا من متسلسلة هو `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mtext>ن</mtext></msubsup><msub><mtext>ح</mtext><mtext>ر</mtext></msub><mo>=</mo><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mtext>ن</mtext></msubsup><mo stretchy=\"false\">(</mo><mn>4</mn><mtext>ر</mtext><mo>−</mo><mn>5</mn><mo stretchy=\"false\">)</mo></mrow></math>`، فما مجموع أول ٧٢ حدًا فيها؟\n- [ ] option-1 | ٢٦٨٢\n- [ ] option-2 | ١٣٤١\n- [ ] option-3 | ٨٥٤١\n- [x] option-4 | ١٠١٥٢\nexplanation:\nالحد العام هو `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mtext>ر</mtext></msub><mo>=</mo><mn>4</mn><mtext>ر</mtext><mo>−</mo><mn>5</mn></mrow></math>`؛ لذا `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>1</mn></msub><mo>=</mo><mo>−</mo><mn>1</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>72</mn></msub><mo>=</mo><mn>4</mn><mo stretchy=\"false\">(</mo><mn>72</mn><mo stretchy=\"false\">)</mo><mo>−</mo><mn>5</mn><mo>=</mo><mn>283</mn></mrow></math>`، والفرق ثابت ويساوي ٤.\n\nمجموع أول ٧٢ حدًا هو `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>72</mn></msub><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>72</mn><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><mo>+</mo><mn>283</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>36</mn><mo>×</mo><mn>282</mn><mo>=</mo><mn>10152</mn></mrow></math>`.\n\nوبتفكيك رمز الجمع نحصل على النتيجة نفسها: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>4</mn><mo>×</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><mn>72</mn><mo>×</mo><mn>73</mn></mrow><mn>2</mn></mfrac></mstyle><mo>−</mo><mn>5</mn><mo>×</mo><mn>72</mn><mo>=</mo><mn>10152</mn></mrow></math>`.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### اختبار ذاتي — الوحدة الثالثة\n:::\n\n:::exam-question\nid: math-t-p057-q07\ntitle: الكتاب · ص 55 · PDF 57 · السؤال 3\nquestion: متسلسلة حسابية يعطى مجموع أول ن حداً منها `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mn>5</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mo>−</mo><mn>3</mn><mtext>ن</mtext></mrow></math>` جد الحد العام لهذه المتسلسلة.\nreference: الكتاب · ص 55 · PDF 57 · السؤال 3\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nمتسلسلة حسابية يعطى مجموع أول ن حداً منها `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mn>5</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mo>−</mo><mn>3</mn><mtext>ن</mtext></mrow></math>` جد الحد العام لهذه المتسلسلة.\n\n### اختبار ذاتي — الوحدة الثالثة\nfinal-answer:\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>ح</mtext><mtext>ن</mtext></msub><mo>=</mo><mn>10</mn><mtext>ن</mtext><mo>−</mo><mn>8</mn></mrow></math>`.\nsolution:\nالحد ذي الرتبة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext></mrow></math>` هو الفرق بين مجموع أول `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext></mrow></math>` حدًا ومجموع أول `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext><mo>−</mo><mn>1</mn></mrow></math>` حدًا:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mtext>ن</mtext></msub><mo>=</mo><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>−</mo><msub><mtext>جـ</mtext><mrow><mtext>ن</mtext><mo>−</mo><mn>1</mn></mrow></msub></mrow></math>`.\n\nنعوض `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mn>5</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mo>−</mo><mn>3</mn><mtext>ن</mtext></mrow></math>`:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mtext>ن</mtext></msub><mo>=</mo><mn>5</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mo>−</mo><mn>3</mn><mtext>ن</mtext><mo>−</mo><mo stretchy=\"false\">{</mo><mn>5</mn><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mo>−</mo><mn>3</mn><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">}</mo></mrow></math>`.\n\nبتوسيع الأقواس يكون `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mrow><mtext>ن</mtext><mo>−</mo><mn>1</mn></mrow></msub><mo>=</mo><mn>5</mn><msup><mtext>ن</mtext><mn>2</mn></msup><mo>−</mo><mn>13</mn><mtext>ن</mtext><mo>+</mo><mn>8</mn></mrow></math>`، وبالتالي `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mtext>ن</mtext></msub><mo>=</mo><mn>10</mn><mtext>ن</mtext><mo>−</mo><mn>8</mn></mrow></math>`.\n\nعند `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext><mo>=</mo><mn>1</mn></mrow></math>` يعطي القانون الحد الأول ٢، وهو يساوي `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><mn>5</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>2</mn></mrow></math>`، فالقانون صالح من الحد الأول.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::mcq\nid: math-e-p048-q01\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 1 · ٢٠٢٢ الأولى\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 1 · ٢٠٢٢ الأولى\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 1 · ٢٠٢٢ الأولى\nquestion: ما قيمة الحد الأخير في المتسلسلة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>60</mn></msubsup><mo stretchy=\"false\">(</mo><mn>12</mn><mo>−</mo><mtext>ر</mtext><mo stretchy=\"false\">)</mo></mrow></math>`؟\n- [x] option-1 | −٤٨\n- [ ] option-2 | ١١\n- [ ] option-3 | ٤٨\n- [ ] option-4 | ٧٢\nexplanation:\nالمطلوب هو الحد الأخير، لا مجموع الحدود. دليل الحد الأخير هو ر = ٦٠؛ نعوض به في قاعدة الحد:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>12</mn><mo>−</mo><mn>60</mn><mo>=</mo><mo>−</mo><mn>48.</mn></mrow></math>`\n\nإذن **الحد الأخير −٤٨**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p048-q02\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 2 · ٢٠٢١\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 2 · ٢٠٢١\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 2 · ٢٠٢١\nquestion: ما هو الحد السادس في المتسلسلة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>60</mn></msubsup><mo stretchy=\"false\">(</mo><mn>8</mn><mo>−</mo><mn>2</mn><mtext>ر</mtext><mo stretchy=\"false\">)</mo></mrow></math>`؟\n- [x] option-1 | −٤\n- [ ] option-2 | ٦\n- [ ] option-3 | ٨\n- [ ] option-4 | ٢٠\nexplanation:\nنحسب الحد السادس بالتعويض عن دليل الحد ر بـ ٦ في العبارة الموجودة تحت إشارة الجمع:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>8</mn><mo>−</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>6</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>8</mn><mo>−</mo><mn>12</mn><mo>=</mo><mo>−</mo><mn>4.</mn></mrow></math>`\n\nإذن **الحد السادس −٤**؛ أما الحد الأول فقيمته ٦.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p048-q03\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 3 · ٢٠٢٠ الأولى\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 3 · ٢٠٢٠ الأولى\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 3 · ٢٠٢٠ الأولى\nquestion: ما قيمة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ن</mtext><mo>=</mo><mn>1</mn></mrow><mn>5</mn></msubsup><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo></mrow></math>`؟\n- [x] option-1 | ٥\n- [ ] option-2 | ٦\n- [ ] option-3 | ٧\n- [ ] option-4 | ٣\nexplanation:\nنعوض ن بالأعداد من ١ إلى ٥ ثم نجمع الحدود الناتجة:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>2</mn><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>3</mn><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>4</mn><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>5</mn><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mo>−</mo><mn>1</mn><mo>+</mo><mn>0</mn><mo>+</mo><mn>1</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>5.</mn></mrow></math>`\n\nإذن **قيمة المجموع ٥**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p048-q04\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 4 · ٢٠٢٠ الثانية\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 4 · ٢٠٢٠ الثانية\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 4 · ٢٠٢٠ الثانية\nquestion: إذا كانت `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><msup><mtext>ن</mtext><mn>2</mn></msup><mo>+</mo><mn>2</mn><mtext>ن</mtext></mrow></math>` تمثل مجموع متسلسلة حسابية منتهية، فما حدها الثاني؟\n- [ ] option-1 | ٣\n- [ ] option-2 | ٨\n- [x] option-3 | ٥\n- [ ] option-4 | ١١\nexplanation:\nقانون المعطى يعطي مجموع الحدود، وليس الحد نفسه. نستخرج الحد الثاني بطرح مجموع أول حد من مجموع أول حدين:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>=</mo><msup><mn>2</mn><mn>2</mn></msup><mo>+</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>8</mn><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><msup><mn>1</mn><mn>2</mn></msup><mo>+</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>3.</mn></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>2</mn></msub><mo>=</mo><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>−</mo><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><mn>8</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>5.</mn></mrow></math>`\n\nإذن **الحد الثاني ٥**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p048-q05\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 5 · ٢٠٢٠ الثانية\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 5 · ٢٠٢٠ الثانية\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 5 · ٢٠٢٠ الثانية\nquestion: ما الحد الثالث في المتسلسلة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>8</mn></msubsup><mo stretchy=\"false\">(</mo><msup><mtext>ر</mtext><mn>2</mn></msup><mo>−</mo><mn>4</mn><mtext>ر</mtext><mo stretchy=\"false\">)</mo></mrow></math>`؟\n- [ ] option-1 | صفر\n- [ ] option-2 | ٧\n- [ ] option-3 | ٣\n- [x] option-4 | −٣\nexplanation:\nلإيجاد الحد الثالث نضع ر = ٣ في قاعدة الحد، ولا نجمع أول ثلاثة حدود:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msup><mn>3</mn><mn>2</mn></msup><mo>−</mo><mn>4</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>9</mn><mo>−</mo><mn>12</mn><mo>=</mo><mo>−</mo><mn>3.</mn></mrow></math>`\n\nإذن **الحد الثالث −٣**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p048-q06\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 6 · ٢٠٢٠ الثالثة\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 6 · ٢٠٢٠ الثالثة\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 6 · ٢٠٢٠ الثالثة\nquestion: ما المتسلسلة التي حدها الثالث يساوي ١٠؟\n- [ ] option-1 | `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>5</mn></msubsup><mo stretchy=\"false\">(</mo><msup><mtext>ر</mtext><mn>2</mn></msup><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`\n- [x] option-2 | `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>5</mn></msubsup><mo stretchy=\"false\">(</mo><msup><mtext>ر</mtext><mn>2</mn></msup><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`\n- [ ] option-3 | `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>5</mn></msubsup><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ر</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`\n- [ ] option-4 | `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mn>5</mn></msubsup><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ر</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`\nexplanation:\nنختبر الحد الثالث بوضع ر = ٣ في كل قاعدة:\n\n- أ: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msup><mn>3</mn><mn>2</mn></msup><mo>−</mo><mn>1</mn><mo>=</mo><mn>8</mn></mrow></math>`.\n- ب: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msup><mn>3</mn><mn>2</mn></msup><mo>+</mo><mn>1</mn><mo>=</mo><mn>10</mn></mrow></math>`.\n- ج: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>1</mn><mo>=</mo><mn>7</mn></mrow></math>`.\n- د: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>−</mo><mn>1</mn><mo>=</mo><mn>5</mn></mrow></math>`.\n\nإذن **الخيار ب** وحده يعطي الحد الثالث ١٠.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p048-q07\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 7 · ٢٠٢٠ الثالثة\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 7 · ٢٠٢٠ الثالثة\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 7 · ٢٠٢٠ الثالثة\nquestion: ما قيمة الحد السادس للمتتالية −٨، −٥، −٢، …؟\n- [ ] option-1 | ١\n- [ ] option-2 | ٣\n- [ ] option-3 | ٩\n- [x] option-4 | ٧\nexplanation:\nالفرق بين كل حدين متتاليين ثابت:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><mo>−</mo><mn>5</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mo>−</mo><mn>8</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>3.</mn></mrow></math>`\n\nنستخدم `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mtext>ن</mtext></msub><mo>=</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext>د</mtext></mrow></math>`، فيكون:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>6</mn></msub><mo>=</mo><mo>−</mo><mn>8</mn><mo>+</mo><mn>5</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>7.</mn></mrow></math>`\n\nإذن **الحد السادس ٧**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p048-q08\ntitle: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 8 · ٢٠٢٠ الثالثة\nkicker: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 8 · ٢٠٢٠ الثالثة\nreference: مجموعة الامتحانات · ص 49 · PDF 48 · السؤال 8 · ٢٠٢٠ الثالثة\nquestion: ما الحد الثالث للمتسلسلة الحسابية التي مجموع أول ن حد فيها يساوي `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><msup><mtext>ن</mtext><mn>2</mn></msup><mo>+</mo><mn>5</mn><mtext>ن</mtext></mrow></math>`؟\n- [ ] option-1 | ٨\n- [x] option-2 | ١٠\n- [ ] option-3 | ١٢\n- [ ] option-4 | ١٤\nexplanation:\nالحد الثالث هو الفرق بين مجموع أول ثلاثة حدود ومجموع أول حدين:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>3</mn></msub><mo>=</mo><msup><mn>3</mn><mn>2</mn></msup><mo>+</mo><mn>5</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>24</mn><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>=</mo><msup><mn>2</mn><mn>2</mn></msup><mo>+</mo><mn>5</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>14.</mn></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>3</mn></msub><mo>=</mo><msub><mtext>جـ</mtext><mn>3</mn></msub><mo>−</mo><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>=</mo><mn>24</mn><mo>−</mo><mn>14</mn><mo>=</mo><mn>10.</mn></mrow></math>`\n\nإذن **الحد الثالث ١٠**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q01\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 1 · ٢٠٢٢ الأولى\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 1 · ٢٠٢٢ الأولى\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 1 · ٢٠٢٢ الأولى\nquestion: إذا كانت `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><msup><mtext>ن</mtext><mn>2</mn></msup><mo>+</mo><mn>2</mn><mtext>ن</mtext></mrow></math>`، تمثل مجموع متسلسلة حسابية منتهية فما حدها الثاني؟\n- [ ] option-1 | ٣\n- [ ] option-2 | ٨\n- [x] option-3 | ٥\n- [ ] option-4 | ١١\nexplanation:\nنميز مجموع أول ن حد عن الحد النوني نفسه. مجموع أول حدين `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>=</mo><msup><mn>2</mn><mn>2</mn></msup><mo>+</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>8</mn></mrow></math>`، ومجموع أول حد `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><msup><mn>1</mn><mn>2</mn></msup><mo>+</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>3</mn></mrow></math>`؛ لذلك:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>2</mn></msub><mo>=</mo><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>−</mo><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><mn>8</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>5.</mn></mrow></math>`\n\nإذن **الحد الثاني ٥**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q02\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 2 · ٢٠١٩ الأولى\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 2 · ٢٠١٩ الأولى\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 2 · ٢٠١٩ الأولى\nquestion: ما مجموع الحدود الأربعة الأولى `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mi mathvariant=\"normal\">∞</mi></msubsup><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mtext>ر</mtext></msup><mo>×</mo><msup><mtext>ر</mtext><mn>2</mn></msup></mrow></math>`؟\n- [x] option-1 | ١٠\n- [ ] option-2 | ٢٠\n- [ ] option-3 | ٣٠\n- [ ] option-4 | −٢٠\nexplanation:\nالمطلوب أربعة حدود فقط، رغم ظهور ∞ في المتسلسلة الأصلية. إشارة الحد سالبة عند الدليل الفردي وموجبة عند الزوجي:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mn>1</mn></msup><mo stretchy=\"false\">(</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mo>+</mo><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mo stretchy=\"false\">(</mo><mn>2</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mo>+</mo><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mn>3</mn></msup><mo stretchy=\"false\">(</mo><mn>3</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mo>+</mo><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><msup><mo stretchy=\"false\">)</mo><mn>4</mn></msup><mo stretchy=\"false\">(</mo><mn>4</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo>=</mo><mo>−</mo><mn>1</mn><mo>+</mo><mn>4</mn><mo>−</mo><mn>9</mn><mo>+</mo><mn>16</mn><mo>=</mo><mn>10.</mn></mrow></math>`\n\nإذن **مجموع الحدود الأربعة ١٠**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q03\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 3 · ٢٠١٩ الثانية\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 3 · ٢٠١٩ الثانية\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 3 · ٢٠١٩ الثانية\nquestion: إذا كان مجموع أول أربعة حدود من المتسلسلة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msubsup><mo>∑</mo><mrow><mtext>ر</mtext><mo>=</mo><mn>1</mn></mrow><mi mathvariant=\"normal\">∞</mi></msubsup><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ر</mtext><mo>+</mo><mtext>ب</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>8</mn></mrow></math>`، فما قيمة ب؟\n- [ ] option-1 | ٤\n- [ ] option-2 | ٣\n- [ ] option-3 | −٤\n- [x] option-4 | −٣\nexplanation:\nنكتب مجموع أول أربعة حدود بالتعويض عن ر من ١ إلى ٤:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mn>2</mn><mo>+</mo><mtext>ب</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>4</mn><mo>+</mo><mtext>ب</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>6</mn><mo>+</mo><mtext>ب</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>8</mn><mo>+</mo><mtext>ب</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>20</mn><mo>+</mo><mn>4</mn><mtext>ب</mtext><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\nبما أن المجموع ٨، فإن:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>20</mn><mo>+</mo><mn>4</mn><mtext>ب</mtext><mo>=</mo><mn>8</mn><mo>⇒</mo><mn>4</mn><mtext>ب</mtext><mo>=</mo><mo>−</mo><mn>12</mn><mo>⇒</mo><mtext>ب</mtext><mo>=</mo><mo>−</mo><mn>3.</mn></mrow></math>`\n\nإذن **ب = −٣**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q04\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 4 · ٢٠١٩ الثانية\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 4 · ٢٠١٩ الثانية\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 4 · ٢٠١٩ الثانية\nquestion: متسلسلة حسابية حدها الأول −٣، وأساسها −٢، فما مجموع أول ١٠ حدود منها؟\n- [x] option-1 | −١٢٠\n- [ ] option-2 | −١٠٥\n- [ ] option-3 | −٩٠\n- [ ] option-4 | ١٢٠\nexplanation:\nالمعطيات: الحد الأول −٣، والأساس −٢، وعدد الحدود ١٠. نطبق قانون المجموع:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mtext>د</mtext><mo stretchy=\"false\">]</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>10</mn></msub><mo>=</mo><mfrac><mn>10</mn><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>9</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mn>5</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>6</mn><mo>−</mo><mn>18</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mo>−</mo><mn>120.</mn></mrow></math>`\n\nإذن **مجموع أول عشرة حدود −١٢٠**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q05\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 5 · تجريبي سلفيت\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 5 · تجريبي سلفيت\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 5 · تجريبي سلفيت\nquestion: قيمة س في المتسلسلة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mn>8</mn></mfrac></mstyle><mo>+</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>2</mn><mn>8</mn></mfrac></mstyle><mo>+</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>3</mn><mn>8</mn></mfrac></mstyle><mo>+</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>4</mn><mn>8</mn></mfrac></mstyle><mo>+</mo><mtext>س</mtext></mrow></math>` هي:\n- [ ] option-1 | ١\n- [x] option-2 | $\\dfrac58$\n- [ ] option-3 | $\\dfrac68$\n- [ ] option-4 | $\\dfrac78$\nexplanation:\nالفرق بين كل حدين متتاليين هو `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mfrac><mn>1</mn><mn>8</mn></mfrac></mrow></math>`. لذلك يكون الحد الذي يلي `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mfrac><mn>4</mn><mn>8</mn></mfrac></mrow></math>`:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>س</mtext><mo>=</mo><mfrac><mn>4</mn><mn>8</mn></mfrac><mo>+</mo><mfrac><mn>1</mn><mn>8</mn></mfrac><mo>=</mo><mfrac><mn>5</mn><mn>8</mn></mfrac><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\nإذن **س = ٥⁄٨**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q06\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 6 · تجريبي سلفيت\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 6 · تجريبي سلفيت\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 6 · تجريبي سلفيت\nquestion: أي المتتاليات التالية حسابية؟\n- [ ] option-1 | ٨، ٣، −٢، −٥\n- [ ] option-2 | ٢، ٤، ٨، ١٦\n- [x] option-3 | −٢، ٠، ٢، ٤\n- [ ] option-4 | ٥، ١٠، ٢٥، ٤٥\nexplanation:\nشرط المتتالية الحسابية ثبات الفرق بين كل حدين متتاليين. نحسب الفروق:\n\n- أ: −٥، −٥، −٣؛ ليست ثابتة.\n- ب: ٢، ٤، ٨؛ ليست ثابتة.\n- ج: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>0</mn><mo>−</mo><mo stretchy=\"false\">(</mo><mo>−</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>2</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo>−</mo><mn>0</mn><mo>=</mo><mn>2</mn></mrow></math>`، و`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>4</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>2</mn></mrow></math>`.\n- د: ٥، ١٥، ٢٠؛ ليست ثابتة.\n\nإذن **−٢، ٠، ٢، ٤** متتالية حسابية أساسها ٢.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q07\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 7 · تجريبي أريحا\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 7 · تجريبي أريحا\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 7 · تجريبي أريحا\nquestion: ما أساس المتسلسلة الحسابية التي يعطى مجموعها بالعلاقة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mn>4</mn><mtext>ن</mtext><mo>−</mo><msup><mtext>ن</mtext><mn>2</mn></msup></mrow></math>`؟\n- [ ] option-1 | ٢\n- [x] option-2 | −٢\n- [ ] option-3 | ٣\n- [ ] option-4 | ١\nexplanation:\nنستخرج حدين متتاليين من المجموع المعطى. عند ن = ١:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>1</mn></msub><mo>=</mo><msub><mtext>جـ</mtext><mn>1</mn></msub><mo>=</mo><mn>4</mn><mo stretchy=\"false\">(</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>−</mo><msup><mn>1</mn><mn>2</mn></msup><mo>=</mo><mn>3.</mn></mrow></math>`\n\nوعند ن = ٢، `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>2</mn></msub><mo>=</mo><mn>8</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>4</mn></mrow></math>`، ومنه `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>2</mn></msub><mo>=</mo><mn>4</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>1</mn></mrow></math>`. إذن الأساس:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><msub><mtext>أ</mtext><mn>2</mn></msub><mo>−</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>=</mo><mn>1</mn><mo>−</mo><mn>3</mn><mo>=</mo><mo>−</mo><mn>2.</mn></mrow></math>`\n\nإذن **الأساس −٢**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::mcq\nid: math-e-p049-q08\ntitle: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 8 · تجريبي الخليل\nkicker: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 8 · تجريبي الخليل\nreference: مجموعة الامتحانات · ص 50 · PDF 49 · السؤال 8 · تجريبي الخليل\nquestion: إذا كانت س−١، س+٢، س+٥ تشكل متتالية حسابية، فإن قيمة الأساس لهذه المتتالية هو:\n- [ ] option-1 | صفر\n- [ ] option-2 | ١\n- [ ] option-3 | ٢\n- [x] option-4 | ٣\nexplanation:\nنطرح الحد الأول من الثاني لإيجاد الأساس:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>س</mtext><mo>+</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>−</mo><mo stretchy=\"false\">(</mo><mtext>س</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>3.</mn></mrow></math>`\n\nونتحقق من الفرق التالي:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>س</mtext><mo>+</mo><mn>5</mn><mo stretchy=\"false\">)</mo><mo>−</mo><mo stretchy=\"false\">(</mo><mtext>س</mtext><mo>+</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>3.</mn></mrow></math>`\n\nالفروق ثابتة مهما كانت س؛ إذن **الأساس ٣**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### المتسلسلة الحسابية ومجموعها\n:::\n\n:::exam-question\nid: math-e-p050-q01\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 1 · ٢٠٢١\nquestion: جد الحد الأول في المتسلسلة الحسابية التي حدها الأربعون يساوي −٢٤ ومجموع أول أربعين حداً منها يساوي −١٨٠.\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 1 · ٢٠٢١\nanswer-label: إجابة المفتاح المرفق\nbody:\nجد الحد الأول في المتسلسلة الحسابية التي حدها الأربعون يساوي −٢٤ ومجموع أول أربعين حداً منها يساوي −١٨٠.\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n١٥.\nsolution:\nنستخدم مجموع المتسلسلة بدلالة طرفيها: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>+</mo><msub><mtext>أ</mtext><mtext>ن</mtext></msub><mo stretchy=\"false\">)</mo></mrow></math>`. المعطيات ن = ٤٠، والحد الأخير −٢٤، والمجموع −١٨٠؛ لذلك:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo>−</mo><mn>180</mn><mo>=</mo><mfrac><mn>40</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>−</mo><mn>24</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>20</mn><mo stretchy=\"false\">(</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>−</mo><mn>24</mn><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>1</mn></msub><mo>−</mo><mn>24</mn><mo>=</mo><mo>−</mo><mn>9</mn><mo>⇒</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>=</mo><mn>15.</mn></mrow></math>`\n\nإذن **الحد الأول ١٥**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q02\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 2 · ٢٠٢٠ الأولى\nquestion: ما مجموع أول خمس حدود من متسلسلة حسابية مجموع حديها الثاني والرابع يساوي ١٤، ومجموع حديها الثالث والخامس يساوي ١٨؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 2 · ٢٠٢٠ الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nما مجموع أول خمس حدود من متسلسلة حسابية مجموع حديها الثاني والرابع يساوي ١٤، ومجموع حديها الثالث والخامس يساوي ١٨؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n٣٥.\nsolution:\nنرمز للحد الأول بـ a وللأساس بـ d. من مجموع الحدين الثاني والرابع:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>3</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>14</mn><mo>⇒</mo><mtext>أ</mtext><mo>+</mo><mn>2</mn><mtext>د</mtext><mo>=</mo><mn>7.</mn></mrow></math>`\n\nومن مجموع الحدين الثالث والخامس:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>2</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>4</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>18</mn><mo>⇒</mo><mtext>أ</mtext><mo>+</mo><mn>3</mn><mtext>د</mtext><mo>=</mo><mn>9.</mn></mrow></math>`\n\nبطرح المعادلتين نجد `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><mn>2</mn></mrow></math>` ثم `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext><mo>=</mo><mn>3</mn></mrow></math>`. وعليه:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>5</mn></msub><mo>=</mo><mfrac><mn>5</mn><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>4</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mfrac><mn>5</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><mn>14</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>35.</mn></mrow></math>`\n\nإذن **مجموع أول خمسة حدود ٣٥**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q03\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 3 · ٢٠٢٠ الثانية\nquestion: إذا كان مجموع أول ٥٠ حد من متسلسلة حسابية يساوي ٦٢٥٠، وحدها الأول ٣، جد حدها الأخير؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 3 · ٢٠٢٠ الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nإذا كان مجموع أول ٥٠ حد من متسلسلة حسابية يساوي ٦٢٥٠، وحدها الأول ٣، جد حدها الأخير؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n٢٤٧.\nsolution:\nقاعدة المجموع بدلالة الحدين الأول والأخير هي `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><msub><mtext>أ</mtext><mn>1</mn></msub><mo>+</mo><msub><mtext>أ</mtext><mtext>ن</mtext></msub><mo stretchy=\"false\">)</mo></mrow></math>`. نعوض ن = ٥٠، والمجموع ٦٢٥٠، والحد الأول ٣:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>6250</mn><mo>=</mo><mfrac><mn>50</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><mn>3</mn><mo>+</mo><msub><mtext>أ</mtext><mn>50</mn></msub><mo stretchy=\"false\">)</mo><mo>=</mo><mn>25</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo>+</mo><msub><mtext>أ</mtext><mn>50</mn></msub><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>250</mn><mo>=</mo><mn>3</mn><mo>+</mo><msub><mtext>أ</mtext><mn>50</mn></msub><mo>⇒</mo><msub><mtext>أ</mtext><mn>50</mn></msub><mo>=</mo><mn>247.</mn></mrow></math>`\n\nإذن **الحد الأخير ٢٤٧**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q04\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 4 · ٢٠٢٠ الثالثة\nquestion: أجد مجموع أول ١٠ حدود للمتسلسلة الحسابية $1+4+7+\\ldots$.\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 4 · ٢٠٢٠ الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nأجد مجموع أول ١٠ حدود للمتسلسلة الحسابية $1+4+7+\\ldots$.\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n١٤٥.\nsolution:\nالحد الأول ١ والأساس `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>4</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>3</mn></mrow></math>`. نحسب مجموع عشرة حدود:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>10</mn></msub><mo>=</mo><mfrac><mn>10</mn><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mn>9</mn><mo stretchy=\"false\">(</mo><mn>3</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mn>5</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo>+</mo><mn>27</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>145.</mn></mrow></math>`\n\nإذن **المجموع ١٤٥**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q05\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 5 · ٢٠٢٠ الثالثة\nquestion: متسلسلة حسابية فيها ع₃ = ٥، ع₉ = ١٧، أوجد كلاً من أساسها وحدها الأول؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 5 · ٢٠٢٠ الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nمتسلسلة حسابية فيها ع₃ = ٥، ع₉ = ١٧، أوجد كلاً من أساسها وحدها الأول؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\nالأساس = ٢، حدها الأول = ١.\nsolution:\nمن قانون الحد العام:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>3</mn></msub><mo>=</mo><mtext>أ</mtext><mo>+</mo><mn>2</mn><mtext>د</mtext><mo>=</mo><mn>5</mn><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mtext>أ</mtext><mn>9</mn></msub><mo>=</mo><mtext>أ</mtext><mo>+</mo><mn>8</mn><mtext>د</mtext><mo>=</mo><mn>17.</mn></mrow></math>`\n\nبطرح المعادلتين:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>6</mn><mtext>د</mtext><mo>=</mo><mn>12</mn><mo>⇒</mo><mtext>د</mtext><mo>=</mo><mn>2.</mn></mrow></math>`\n\nثم نعوض في الأولى: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext><mo>+</mo><mn>4</mn><mo>=</mo><mn>5</mn></mrow></math>`، فيكون `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext><mo>=</mo><mn>1</mn></mrow></math>`. إذن **الأساس ٢ والحد الأول ١**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q06\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 6 · ٢٠١٩ الأولى\nquestion: اكتب أول خمس حدود لمتسلسلة حسابية مجموع حديها الثاني والتاسع يساوي ٢٥، ومجموع حديها الثالث والسابع يساوي ٢٠؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 6 · ٢٠١٩ الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nاكتب أول خمس حدود لمتسلسلة حسابية مجموع حديها الثاني والتاسع يساوي ٢٥، ومجموع حديها الثالث والسابع يساوي ٢٠؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n−١٠، −٥، ٠، ٥، ١٠.\nsolution:\nلتكن a أول حد وd الأساس. نحول المعطيات إلى معادلتين:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>8</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>25</mn><mo>⇒</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>9</mn><mtext>د</mtext><mo>=</mo><mn>25</mn><mo separator=\"true\">,</mo></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>2</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><mo>+</mo><mn>6</mn><mtext>د</mtext><mo stretchy=\"false\">)</mo><mo>=</mo><mn>20</mn><mo>⇒</mo><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>8</mn><mtext>د</mtext><mo>=</mo><mn>20.</mn></mrow></math>`\n\nنطرح الثانية من الأولى فنجد `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><mn>5</mn></mrow></math>`؛ ثم `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mtext>أ</mtext><mo>+</mo><mn>40</mn><mo>=</mo><mn>20</mn></mrow></math>`، ومنه `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>أ</mtext><mo>=</mo><mo>−</mo><mn>10</mn></mrow></math>`. بإضافة ٥ في كل مرة تكون **أول خمسة حدود: −١٠، −٥، ٠، ٥، ١٠**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q07\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 7 · ٢٠١٩ الثانية\nquestion: إذا كان مجموع أول ن حداً من متسلسلة حسابية يعطى بالعلاقة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mtext>ن</mtext><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ن</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>` جد الحد العاشر؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 7 · ٢٠١٩ الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nإذا كان مجموع أول ن حداً من متسلسلة حسابية يعطى بالعلاقة `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mtext>ن</mtext><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ن</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>` جد الحد العاشر؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n٣٩.\nsolution:\nالمعطى هو `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mtext>ن</mtext></msub><mo>=</mo><mtext>ن</mtext><mo stretchy=\"false\">(</mo><mn>2</mn><mtext>ن</mtext><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></math>`، ولذلك نستخرج الحد العاشر بالفرق بين مجموعين متتاليين:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>10</mn></msub><mo>=</mo><mn>10</mn><mo stretchy=\"false\">(</mo><mn>21</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>210</mn><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mtext>جـ</mtext><mn>9</mn></msub><mo>=</mo><mn>9</mn><mo stretchy=\"false\">(</mo><mn>19</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>171.</mn></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>10</mn></msub><mo>=</mo><msub><mtext>جـ</mtext><mn>10</mn></msub><mo>−</mo><msub><mtext>جـ</mtext><mn>9</mn></msub><mo>=</mo><mn>210</mn><mo>−</mo><mn>171</mn><mo>=</mo><mn>39.</mn></mrow></math>`\n\nإذن **الحد العاشر ٣٩**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q08\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 8 · تجريبي أريحا\nquestion: إذا كان مجموع أول عشرين حداً من المتسلسلة الحسابية `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>س</mtext><mo>+</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mn>3</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>2</mn><mo>+</mo><mn>5</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>3</mn><mo>+</mo><mn>7</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo>…</mo><mo>=</mo><mn>990</mn></mrow></math>`، فما قيمة حدها ع₁₀؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 8 · تجريبي أريحا\nanswer-label: إجابة المفتاح المرفق\nbody:\nإذا كان مجموع أول عشرين حداً من المتسلسلة الحسابية `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>س</mtext><mo>+</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mn>3</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>2</mn><mo>+</mo><mn>5</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mn>3</mn><mo>+</mo><mn>7</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mo>…</mo><mo>=</mo><mn>990</mn></mrow></math>`، فما قيمة حدها ع₁₀؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n٤٧.\nsolution:\nالحد الأول س، والفرق المشترك `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mn>3</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo>−</mo><mtext>س</mtext><mo>=</mo><mn>1</mn><mo>+</mo><mn>2</mn><mtext>س</mtext></mrow></math>`. نطبق معطى مجموع عشرين حدًّا:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>990</mn><mo>=</mo><mfrac><mn>20</mn><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mtext>س</mtext><mo>+</mo><mn>19</mn><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mn>2</mn><mtext>س</mtext><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mn>10</mn><mo stretchy=\"false\">(</mo><mn>40</mn><mtext>س</mtext><mo>+</mo><mn>19</mn><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\nإذن `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>99</mn><mo>=</mo><mn>40</mn><mtext>س</mtext><mo>+</mo><mn>19</mn></mrow></math>`، ومنه **س = ٢**، فيكون الحد الأول ٢ والأساس ٥. لذا:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>10</mn></msub><mo>=</mo><mn>2</mn><mo>+</mo><mn>9</mn><mo stretchy=\"false\">(</mo><mn>5</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>47.</mn></mrow></math>`\n\nإذن **الحد العاشر ٤٧**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q09\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 9 · تجريبي جنوب نابلس\nquestion: إذا كانت ٢، س، …، ص، ١٧ تمثل متتالية حسابية، ١٩، ص، ٩، … تمثل متتالية حسابية أخرى، جد قيمة س، ص. ثم ترتيب العدد ١٧ في المتتالية الأولى.\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 9 · تجريبي جنوب نابلس\nanswer-label: إجابة المفتاح المرفق\nbody:\nإذا كانت ٢، س، …، ص، ١٧ تمثل متتالية حسابية، ١٩، ص، ٩، … تمثل متتالية حسابية أخرى، جد قيمة س، ص. ثم ترتيب العدد ١٧ في المتتالية الأولى.\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\nس = ٥، ص = ١٤، الترتيب = ٦.\nsolution:\nفي المتتالية الثانية تكون ص وسطًا حسابيًّا بين ١٩ و٩:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ص</mtext><mo>=</mo><mfrac><mrow><mn>19</mn><mo>+</mo><mn>9</mn></mrow><mn>2</mn></mfrac><mo>=</mo><mn>14.</mn></mrow></math>`\n\nفي المتتالية الأولى ص = ١٤ يسبق ١٧ مباشرة، فيكون أساسها `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>17</mn><mo>−</mo><mn>14</mn><mo>=</mo><mn>3</mn></mrow></math>`، ومنه **س = ٢ + ٣ = ٥**. ولإيجاد ترتيب ١٧:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>17</mn><mo>=</mo><mn>2</mn><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mn>3</mn><mo>⇒</mo><mn>15</mn><mo>=</mo><mn>3</mn><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>⇒</mo><mtext>ن</mtext><mo>=</mo><mn>6.</mn></mrow></math>`\n\nإذن **س = ٥، ص = ١٤، ورتبة ١٧ هي السادسة**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q10\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 10 · تجريبي سلفيت\nquestion: جد مجموع الحدود السبعة الأولى من المتسلسلة الحسابية `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mi>log</mi><mo>⁡</mo><mtext>أ</mtext><mo>+</mo><mi>log</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>أب</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mi>log</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><msup><mtext>ب</mtext><mn>2</mn></msup><mo stretchy=\"false\">)</mo><mo>+</mo><mi>log</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><msup><mtext>ب</mtext><mn>3</mn></msup><mo stretchy=\"false\">)</mo><mo>+</mo><mo>…</mo></mrow></math>`.\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 10 · تجريبي سلفيت\nanswer-label: إجابة المفتاح المرفق\nbody:\nجد مجموع الحدود السبعة الأولى من المتسلسلة الحسابية `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mi>log</mi><mo>⁡</mo><mtext>أ</mtext><mo>+</mo><mi>log</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>أب</mtext><mo stretchy=\"false\">)</mo><mo>+</mo><mi>log</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><msup><mtext>ب</mtext><mn>2</mn></msup><mo stretchy=\"false\">)</mo><mo>+</mo><mi>log</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><msup><mtext>ب</mtext><mn>3</mn></msup><mo stretchy=\"false\">)</mo><mo>+</mo><mo>…</mo></mrow></math>`.\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>7</mn><mo stretchy=\"false\">(</mo><mi>log</mi><mo>⁡</mo><mtext>أ</mtext><mo>+</mo><mn>3</mn><mi>log</mi><mo>⁡</mo><mtext>ب</mtext><mo stretchy=\"false\">)</mo></mrow></math>`.\nsolution:\nبشرط أن تكون أ وب موجبتين، نستخدم `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mi>log</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mtext>أ</mtext><msup><mtext>ب</mtext><mtext>ر</mtext></msup><mo stretchy=\"false\">)</mo><mo>=</mo><mi>log</mi><mo>⁡</mo><mtext>أ</mtext><mo>+</mo><mtext>ر</mtext><mi>log</mi><mo>⁡</mo><mtext>ب</mtext></mrow></math>`. الحد الأول `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mi>log</mi><mo>⁡</mo><mtext>أ</mtext></mrow></math>` والأساس `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mi>log</mi><mo>⁡</mo><mtext>ب</mtext></mrow></math>`. إذن:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>جـ</mtext><mn>7</mn></msub><mo>=</mo><mfrac><mn>7</mn><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mi>log</mi><mo>⁡</mo><mtext>أ</mtext><mo>+</mo><mn>6</mn><mi>log</mi><mo>⁡</mo><mtext>ب</mtext><mo stretchy=\"false\">]</mo><mo>=</mo><mn>7</mn><mo stretchy=\"false\">(</mo><mi>log</mi><mo>⁡</mo><mtext>أ</mtext><mo>+</mo><mn>3</mn><mi>log</mi><mo>⁡</mo><mtext>ب</mtext><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\nويمكن رؤية ذلك بجمع معاملات `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mi>log</mi><mo>⁡</mo><mtext>ب</mtext></mrow></math>`: `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>0</mn><mo>+</mo><mn>1</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>3</mn><mo>+</mo><mn>4</mn><mo>+</mo><mn>5</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>21</mn></mrow></math>`.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q11\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 11 · تجريبي سلفيت\nquestion: كم حداً يلزم أخذه من المتسلسلة الحسابية $-8+(-4)+0+\\ldots$ ليصبح المجموع ٧٢؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 11 · تجريبي سلفيت\nanswer-label: إجابة المفتاح المرفق\nbody:\nكم حداً يلزم أخذه من المتسلسلة الحسابية $-8+(-4)+0+\\ldots$ ليصبح المجموع ٧٢؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n٩.\nsolution:\nالحد الأول −٨ والأساس ٤. نضع المجموع مساويًا لـ ٧٢:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>72</mn><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>8</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mn>4</mn><mo stretchy=\"false\">]</mo><mo>=</mo><mn>2</mn><mtext>ن</mtext><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>5</mn><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msup><mtext>ن</mtext><mn>2</mn></msup><mo>−</mo><mn>5</mn><mtext>ن</mtext><mo>−</mo><mn>36</mn><mo>=</mo><mn>0</mn><mo>⇒</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>9</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>+</mo><mn>4</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>0.</mn></mrow></math>`\n\nنرفض −٤ لأن عدد الحدود موجب؛ إذن **نحتاج ٩ حدود**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q12\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 12 · تجريبي شرق غزة\nquestion: لديك المتسلسلة الحسابية $16+12+8+\\ldots$، جد مجموع أول عشرة حدود بدءاً من الحد الثامن؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 12 · تجريبي شرق غزة\nanswer-label: إجابة المفتاح المرفق\nbody:\nلديك المتسلسلة الحسابية $16+12+8+\\ldots$، جد مجموع أول عشرة حدود بدءاً من الحد الثامن؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n−٣٠٠.\nsolution:\nالحد الأول ١٦ والأساس −٤. بداية الجزء المطلوب عند الحد الثامن:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>8</mn></msub><mo>=</mo><mn>16</mn><mo>+</mo><mn>7</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>4</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mo>−</mo><mn>12.</mn></mrow></math>`\n\nأخذ عشرة حدود بدءًا من الثامن ينتهي عند الحد السابع عشر، لا الثامن عشر:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>17</mn></msub><mo>=</mo><mn>16</mn><mo>+</mo><mn>16</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>4</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mo>−</mo><mn>48.</mn></mrow></math>`\n\nمجموع هذا الجزء:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mfrac><mn>10</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><mo>−</mo><mn>12</mn><mo>−</mo><mn>48</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mo>−</mo><mn>300.</mn></mrow></math>`\n\nإذن **المجموع −٣٠٠**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q13\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 13 · تجريبي شرق غزة\nquestion: متسلسلة حسابية حدها الأول ٧، وحدها الأخير −١٢، ومجموع حدودها −٥٠، ما عدد الحدود التي يجب أخذها من الحد الرابع ليكون المجموع يساوي صفر؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 13 · تجريبي شرق غزة\nanswer-label: إجابة المفتاح المرفق\nbody:\nمتسلسلة حسابية حدها الأول ٧، وحدها الأخير −١٢، ومجموع حدودها −٥٠، ما عدد الحدود التي يجب أخذها من الحد الرابع ليكون المجموع يساوي صفر؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n٩.\nsolution:\nنحدد أولًا عدد حدود المتسلسلة الأصلية من المجموع وطرفيها:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo>−</mo><mn>50</mn><mo>=</mo><mfrac><mtext>ن</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><mn>7</mn><mo>−</mo><mn>12</mn><mo stretchy=\"false\">)</mo><mo>⇒</mo><mtext>ن</mtext><mo>=</mo><mn>20.</mn></mrow></math>`\n\nومن `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mo>−</mo><mn>12</mn><mo>=</mo><mn>7</mn><mo>+</mo><mn>19</mn><mtext>د</mtext></mrow></math>` نجد `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>د</mtext><mo>=</mo><mo>−</mo><mn>1</mn></mrow></math>`. الحد الرابع `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msub><mtext>أ</mtext><mn>4</mn></msub><mo>=</mo><mn>7</mn><mo>+</mo><mn>3</mn><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>4</mn></mrow></math>`. إذا أخذنا k حدود بدءًا منه، فإن:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>0</mn><mo>=</mo><mfrac><mtext>ك</mtext><mn>2</mn></mfrac><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>4</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ك</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>=</mo><mfrac><mrow><mtext>ك</mtext><mo stretchy=\"false\">(</mo><mn>9</mn><mo>−</mo><mtext>ك</mtext><mo stretchy=\"false\">)</mo></mrow><mn>2</mn></mfrac><mi mathvariant=\"normal\">.</mi></mrow></math>`\n\nنستبعد k = ٠ لأن المطلوب أخذ حدود؛ إذن **نأخذ ٩ حدود**، وهي من ٤ إلى −٤.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p050-q14\ntitle: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 14 · تجريبي نابلس\nquestion: أجد مجموع الأعداد المحصورة بين ١، ٥٠٠ والتي تقبل القسمة على ٣؟\nreference: مجموعة الامتحانات · ص 51 · PDF 50 · السؤال 14 · تجريبي نابلس\nanswer-label: إجابة المفتاح المرفق\nbody:\nأجد مجموع الأعداد المحصورة بين ١، ٥٠٠ والتي تقبل القسمة على ٣؟\n\n### المتسلسلة الحسابية ومجموعها\nfinal-answer:\n٤١٥٨٣.\nsolution:\nالأعداد المطلوبة هي مضاعفات ٣ الواقعة بين ١ و٥٠٠: ٣، ٦، …، ٤٩٨. عددها:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>498</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>166.</mn></mrow></math>`\n\nهي متسلسلة حسابية أولها ٣ وآخرها ٤٩٨، لذلك:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>جـ</mtext><mo>=</mo><mfrac><mn>166</mn><mn>2</mn></mfrac><mo stretchy=\"false\">(</mo><mn>3</mn><mo>+</mo><mn>498</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>83</mn><mo stretchy=\"false\">(</mo><mn>501</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>41583.</mn></mrow></math>`\n\nإذن **المجموع ٤١٥٨٣**.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::\n\n:::exam-question\nid: math-e-p051-q04\ntitle: مجموعة الامتحانات · ص 52 · PDF 51 · السؤال 4 · ٢٠٢١ الثانية\nquestion: كم حداً يلزم أخذه من المتسلسلة $2+6+10+\\ldots$ ليكون المجموع مساوياً ٩٨؟\nreference: مجموعة الامتحانات · ص 52 · PDF 51 · السؤال 4 · ٢٠٢١ الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nكم حداً يلزم أخذه من المتسلسلة $2+6+10+\\ldots$ ليكون المجموع مساوياً ٩٨؟\n\n### المتسلسلة الهندسية ومجموعها\nfinal-answer:\nن = ٧.\nsolution:\nالفرق بين الحدود المتتالية هو `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>6</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>10</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>4</mn></mrow></math>`؛ إذن المتسلسلة **حسابية**، وحدها الأول ٢ وأساسها ٤.\n\nنساوي مجموع أول `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext></mrow></math>` حدًا بالعدد المطلوب:\n\n`mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>98</mn><mo>=</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mtext>ن</mtext><mn>2</mn></mfrac></mstyle><mo stretchy=\"false\">[</mo><mn>2</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo stretchy=\"false\">)</mo><mo>+</mo><mo stretchy=\"false\">(</mo><mtext>ن</mtext><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mn>4</mn><mo stretchy=\"false\">]</mo><mo>=</mo><mn>2</mn><msup><mtext>ن</mtext><mn>2</mn></msup></mrow></math>`.\n\nومنها `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><msup><mtext>ن</mtext><mn>2</mn></msup><mo>=</mo><mn>49</mn></mrow></math>`، فنأخذ `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mtext>ن</mtext><mo>=</mo><mn>7</mn></mrow></math>` لأن عدد الحدود موجب. والتحقق: الحد السابع `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>2</mn><mo>+</mo><mn>6</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>26</mn></mrow></math>`، والمجموع `mathml: <math dir=\"rtl\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><mrow><mn>7</mn><mo stretchy=\"false\">(</mo><mn>2</mn><mo>+</mo><mn>26</mn><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mn>2</mn><mo>=</mo><mn>98</mn></mrow></math>`.\n\nقاعدة الدرس في الرزمة، ص 42–44.\n:::";

